python3 -c 'import pathlib,json,os,subprocess,hashlib,collections; root=pathlib.Path(os.environ["LABVIEW_ENVIRONMENT"]); p=pathlib.Path("benchmark/sources.json"); d=json.loads(p.read_text()); out=[]; ready=root/"readiness.json"; out.append("Readiness SHA256 matches: "+str(hashlib.sha256(ready.read_bytes()).hexdigest()==d["preparation_readiness_sha256"])); out.append("Readiness: "+ready.read_text()); counts=collections.Counter(); failures=[]; raw_checked=0; xml_checked=0; import xml.etree.ElementTree as ET; infos=[]; git=lambda base,args: subprocess.run(["git","-C",str(base)]+args,capture_output=True,check=True).stdout; 
for r in d["repositories"]:
 base=root/r["name"]; head=git(base,["rev-parse","HEAD"]).decode().strip(); license_bytes=(base/r["license_file"]["path"]).read_bytes(); infos.append({"name":r["name"],"head_matches":head==r["commit"],"license_hash_matches":hashlib.sha256(license_bytes).hexdigest()==r["license_file"]["sha256"],"license_text":license_bytes.decode(),"artifacts":len(r["artifacts"])});
 for a in r["artifacts"]:
  b=(base/a["path"]).read_bytes(); blob=git(base,["show",r["commit"]+":"+a["path"]]);
  if len(b)!=a["size"] or hashlib.sha256(b).hexdigest()!=a["sha256"] or b!=blob: failures.append(r["name"]+"/"+a["path"]+": original/hash/blob mismatch")
  v=a["save_version"]; counts[v.get("decoded",v["status"])]+=1
  if "byte_offset" in v:
   raw_checked+=1
   if b[v["byte_offset"]:v["byte_offset"]+4].hex()!=v["raw_hex"]: failures.append(a["path"]+": raw version mismatch")
  elif v.get("method")=="XML root @LVVersion":
   xml_checked+=1
   if ET.fromstring(b).attrib.get("LVVersion","").lower()!=v["raw_hex"].lower(): failures.append(a["path"]+": XML version mismatch")
out.append("Independent originals audit: "+json.dumps(infos)); out.append("Version counts: "+str(counts)); out.append("Raw offset checks: "+str(raw_checked)+"; XML checks: "+str(xml_checked)+"; failures: "+repr(failures)); out.append("Named-file history: "+subprocess.run(["git","log","-3","--format=%H %s","--","benchmark/sources.md","benchmark/sources.json","benchmark/preparation-status.json"],capture_output=True,text=True).stdout); evidence=pathlib.Path(".session/artifacts/review-sources-evidence.txt"); evidence.write_text("\n\n".join(out)); print(evidence.read_text()); review=pathlib.Path(".session/artifacts/review-sources.md"); review.open("a").write("\n## Originals and provenance check\nEvidence: [independent audit](review-sources-evidence.txt). At benchmark/sources.md:11-18, the two license files and all 523 original artifacts were independently compared with manifest hashes and pinned Git blobs; results are recorded in the audit. Declared upstream identity remains offline evidence rather than independently authenticated network provenance. Impact: reproducible local originals, with that provenance limitation; correction: retain the limitation and authenticate upstream separately if stronger provenance is required.\n")'
